(function(){
'use strict';
const boot=window.MW_BOOT||{mode:'unconfigured'},demo=boot.mode==='demo';
const $=s=>document.querySelector(s),esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((n||0)/100);
const date=v=>v?new Date(/^\d{4}-\d{2}-\d{2}$/.test(v)?v+'T12:00:00':v).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—';
const uid=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join(''),initials=n=>n.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('');
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18M17 12h4v5h-4a2.5 2.5 0 0 1 0-5z"/>',file:'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h6"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',message:'<path d="M21 15a3 3 0 0 1-3 3H7l-4 3V6a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3zM7 8h10M7 12h7"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',users:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M17 3a4 4 0 0 1 0 8M18 14a6 6 0 0 1 4 5v2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',down:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5z"/><path d="m8 12 3 3 5-6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',logout:'<path d="M9 4H3v16h6M8 12h13m-5-5 5 5-5 5"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',leaf:'<path d="M20 3C10 2 3 7 4 14c1 7 12 8 15-1 1-3 1-7 1-10ZM3 22 15 9M8 17l-1-5m5 1 5 1"/>',refresh:'<path d="M20 6v5h-5M4 18v-5h5M19 10a7 7 0 0 0-12-5L4 8m1 6a7 7 0 0 0 12 5l3-3"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.file}</svg>`;
const button=(label,action,cls='',ic='')=>`<button class="btn ${cls}" data-action="${action}">${ic?icon(ic):''}${label}</button>`;
let current='overview',adminTab='members',data=null,auth=null,adminView=false,search='',filter='all';
let model;
function seed(){
 const members=[{id:'MW9001',name:'Amara Banda',email:'amara@example.org',phone:'',location:'Dallas, TX',joined:'2026-04-04',status:'ACTIVE',role:'member'},
 {id:'MW9002',name:'Samuel Phiri',email:'samuel@example.org',phone:'',location:'Atlanta, GA',joined:'2026-04-09',status:'ACTIVE',role:'member'},
 {id:'MW9003',name:'Lina Moyo',email:'lina@example.org',phone:'',location:'Houston, TX',joined:'2026-05-01',status:'ACTIVE',role:'member'},
 {id:'MW9004',name:'Peter Zimba',email:'peter@example.org',phone:'',location:'Chicago, IL',joined:'2026-05-05',status:'SUSPENDED',role:'member'}];
 let events=[];let n=0;
 const add=(mid,kind,amount,title,extra={},at='2026-10-09T12:00:00Z')=>{const r=MWLedger.create(events,{memberId:mid,kind,amount,title,note:'Fictional demonstration transaction',requestId:'sample_'+(++n),...extra},'Sample administrator',at,'ev_'+n);events.push(r.event);};
 add('MW9001','CHARGE','15','Fund 006 contribution',{chargeKey:'FUND-006'},'2026-09-02T12:00:00Z');
 add('MW9001','PAYMENT','15','Fund 006 payment',{reference:'DEMO-001',scope:'oldest'},'2026-09-03T12:00:00Z');
 add('MW9001','CHARGE','15','Fund 007 contribution',{chargeKey:'FUND-007'},'2026-09-21T12:00:00Z');
 add('MW9001','PAYMENT','15','Fund 007 payment',{reference:'DEMO-002',scope:'oldest'},'2026-09-23T12:00:00Z');
 add('MW9001','CHARGE','15','Fund 008 contribution',{chargeKey:'FUND-008'},'2026-10-10T12:00:00Z');
 add('MW9001','PAYMENT','50','Payment received',{reference:'DEMO-003',scope:'oldest'},'2026-10-18T12:00:00Z');
 add('MW9002','CHARGE','15','Fund 008 contribution',{chargeKey:'FUND-008'});
 add('MW9003','OPENING_CREDIT','20','Reconciled opening credit');
 return {members,events,documents:[{id:'doc1',title:'Quarterly financial report',category:'Quarterly report',period:'Q3 · 2026',date:'2026-10-09',audience:'members',sample:true},{id:'doc2',title:'Bank reconciliation statement',category:'Bank statement',period:'October 2026',date:'2026-10-09',audience:'members',sample:true},{id:'doc3',title:'General meeting minutes',category:'Meeting minutes',period:'October 2026',date:'2026-10-17',audience:'members',sample:true}],
 messages:[{id:'msg1',title:'Your account, all in one place',body:'Check your contributions, follow your credit balance, and find official documents here. This preview uses fictional records so you can explore safely.',date:'2026-10-21',audience:'members',author:'Leadership',read:false},{id:'msg2',title:'How advance credit works',body:'When a confirmed payment exceeds the selected contribution, the remainder becomes available credit. Each use of that credit appears on your statement. In the live portal, automatic use follows the approved allocation policy.',date:'2026-10-18',audience:'members',author:'Treasury',read:false}],tickets:[],audit:[]};
}
if(demo){try{model=JSON.parse(sessionStorage.getItem('mw-preview-v1'));}catch(e){}if(!model)model=seed();}
function save(){if(demo)sessionStorage.setItem('mw-preview-v1',JSON.stringify(model));}
function demoSnapshot(){const member=model.members[0],s=MWLedger.state(model.events,member.id);return {member,ledger:s,history:[],documents:model.documents.filter(d=>adminView||d.audience==='members'),messages:model.messages.filter(m=>adminView||m.audience==='members'||m.audience===member.id),tickets:model.tickets.filter(t=>adminView||t.memberId===member.id),admin:adminView?{members:model.members.map(m=>({...m,...MWLedger.state(model.events,m.id)})),events:model.events,audit:model.audit,documents:model.documents,messages:model.messages,tickets:model.tickets}:null,ledgerEnabled:true,mode:'demo',canAdmin:true};}
async function firebaseRequest(method,payload){const r=await fetch('https://identitytoolkit.googleapis.com/v1/accounts:'+method+'?key='+encodeURIComponent(boot.apiKey),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const j=await r.json();if(!r.ok)throw new Error(j.error?.message||'Sign-in could not be completed.');return j;}
async function token(){if(!auth)throw new Error('Please sign in.');if(Date.now()>auth.expires){const r=await fetch('https://securetoken.googleapis.com/v1/token?key='+encodeURIComponent(boot.apiKey),{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'refresh_token',refresh_token:auth.refreshToken})});const j=await r.json();if(!r.ok)throw new Error('Your session expired. Please sign in again.');auth.idToken=j.id_token;auth.refreshToken=j.refresh_token;auth.expires=Date.now()+(Number(j.expires_in)-60)*1000;}return auth.idToken;}
async function rpc(action,payload={}){if(demo)return demoRpc(action,payload);const t=await token();return new Promise((resolve,reject)=>{google.script.run.withSuccessHandler(r=>r.ok?resolve(r.data):reject(new Error(r.error||'Request could not be completed.'))).withFailureHandler(()=>reject(new Error('Connection interrupted. Please try again.'))).portalRpc({token:t,action,payload});});}
function demoRpc(action,p){
 const audit=(what)=>model.audit.unshift({at:new Date().toISOString(),actor:adminView?'Sample administrator':'Amara Banda',action:what});
 if(action==='dashboard')return demoSnapshot();
 if(action==='ledger'){if(!adminView)throw new Error('Administrator access required.');p.autoApply=true;const r=MWLedger.create(model.events,p,'Sample administrator',new Date().toISOString(),uid());if(!r.duplicate)model.events.push(r.event);audit('Ledger: '+p.kind+' · '+p.memberId);save();return r;}
 if(action==='accountStatus'){if(!adminView)throw new Error('Administrator access required.');const m=model.members.find(m=>m.id===p.memberId);m.status=p.status;audit(p.status+' · '+m.id);}
 if(action==='resetPassword'){if(!adminView)throw new Error('Administrator access required.');audit('Password reset preview · '+p.memberId);save();return {message:'Preview only. No password-reset email was sent.'};}
 if(action==='acknowledge'){const m=model.messages.find(m=>m.id===p.id);m.read=true;}
 if(action==='ticket'){model.tickets.unshift({id:uid(),memberId:'MW9001',subject:p.subject,body:p.body,date:new Date().toISOString(),status:'OPEN',reply:''});audit('Support request created');}
 if(action==='reply'){const t=model.tickets.find(t=>t.id===p.id);t.reply=p.reply;t.status='REPLIED';audit('Reply to '+t.memberId);}
 if(action==='profileRequest'){model.tickets.unshift({id:uid(),memberId:'MW9001',subject:'Profile update request',body:'Phone: '+p.phone+'\nLocation: '+p.location,date:new Date().toISOString(),status:'OPEN',reply:''});}
 if(action==='publish'){const item={...p,id:uid(),date:new Date().toISOString(),author:'Leadership',sample:true,read:false};if(p.type==='document')model.documents.unshift(item);else model.messages.unshift(item);audit('Published '+p.type+': '+p.title);}
 save();return {ok:true};
}
let toastTimer;function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function modal(title,body){$('#modalBody').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close">${icon('close')}</button></div>${body}`;$('#modal').showModal();}
function empty(title,body,ic='file'){return `<div class="empty">${icon(ic)}<h3>${esc(title)}</h3><p>${esc(body)}</p></div>`;}
async function refresh(){try{data=await rpc('dashboard');if(!data.canAdmin)adminView=false;render();}catch(e){toast(e.message);if(!data)renderAuth('signin',e.message);}}
const pageNames={overview:'Overview',statement:'My statement',funds:'Contributions & credit',documents:'Documents',messages:'Messages',profile:'My profile',admin:'Administration'};
function nav(id,label,ic){return `<button class="nav-item ${current===id?'active':''}" data-page="${id}" ${current===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='messages'&&data.messages.some(m=>!m.read)?'<span class="badge pill">'+data.messages.filter(m=>!m.read).length+'</span>':''}</button>`;}
function brand(){return `<a class="brand" href="https://mgwirizano.net/" target="_blank" rel="noopener"><span class="brand-mark"><img src="https://lh3.googleusercontent.com/d/1S3eEVjZY5yTfOXadnZfYU-1xbWGrykeP" alt="Mgwirizano Watsopano logo"></span><span class="brand-name">Mgwirizano<br>Watsopano<small>MEMBER PORTAL</small></span></a>`;}
function render(){if(!data)return;document.body.classList.toggle('live',!demo);const m=data.member;$('#app').innerHTML=`${demo?'<div class="demo-strip"><strong>INTERACTIVE PREVIEW</strong><span>Fictional records · No live payments or emails</span><button data-action="reset-demo">Reset</button></div>':''}<div class="shell"><div class="mobile-overlay" data-action="menu"></div><aside class="sidebar">${brand()}<div class="nav-label">YOUR MEMBERSHIP</div>${nav('overview','Overview','home')}${nav('statement','My statement','file')}${nav('funds','Contributions & credit','wallet')}${nav('documents','Documents','file')}${nav('messages','Messages','message')}${nav('profile','My profile','user')}${data.canAdmin?'<div class="nav-label">MANAGEMENT</div>'+nav('admin','Admin workspace','users'):''}<div class="sidebar-bottom"><div class="help-card"><strong>We’re here to help.</strong><p>A question about your account or a payment?</p><button class="text-link" style="color:#d4ddc4" data-action="help">Contact leadership ${icon('arrow')}</button></div><div class="user-tile"><span class="avatar">${esc(initials(m.name))}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.id)}</small></div><button class="icon-btn" style="margin-left:auto;color:#a6b7bd" data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open menu">${icon('menu')}</button><span>Member portal</span><span>/</span><strong style="color:var(--ink)">${pageNames[current]}</strong></div><div class="top-actions">${demo?'<button class="text-link desktop-label" data-action="login-preview">Sign-in preview</button>':''}<button class="icon-btn" data-page="messages" aria-label="Open messages">${icon('bell')}</button><span class="avatar">${esc(initials(m.name))}</span></div></header><div class="content">${renderPage()}<footer class="footer"><span>© ${new Date().getFullYear()} Mgwirizano Watsopano · Unity. Benevolence. Support.</span><span>${icon('shield')}${demo?'Preview environment':'Private member account'}</span></footer></div></main></div>`;}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function metric(label,value,foot,ic,color=''){return `<div class="metric"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-value ${color}">${value}</div><div class="metric-bottom">${foot}</div></div>`;}
function transactions(events,limit){let list=events.slice().reverse();if(limit)list=list.slice(0,limit);if(!list.length)return empty('Your statement starts here','Confirmed transactions will appear here once your opening records are reconciled.');return `<div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Date</th><th class="right">Amount</th></tr></thead><tbody>${list.map(e=>`<tr><td><span class="table-icon">${icon(e.kind==='PAYMENT'?'down':e.kind==='CHARGE'?'heart':'wallet')}</span><span class="txn-name">${esc(e.title||labels[e.kind])}<small>${esc(labels[e.kind])}${e.reference?' · '+esc(e.reference):''}</small></span></td><td>${date(e.at)}</td><td class="right amount">${e.kind==='APPLY_CREDIT'?money(e.allocations.reduce((s,a)=>s+a.amount,0)):money(e.amount)}<small>${e.kind==='PAYMENT'?money(e.amount-e.allocations.reduce((s,a)=>s+a.amount,0))+' to credit':e.kind==='CHARGE'?'Contribution due':e.kind==='APPLY_CREDIT'?'Credit applied':''}</small></td></tr>`).join('')}</tbody></table></div>`;}
const labels={CHARGE:'Contribution recorded',PAYMENT:'Payment received',OPENING_CREDIT:'Opening credit',APPLY_CREDIT:'Credit allocation',REFUND:'Credit refund',REVERSAL:'Payment reversed'};
function renderPage(){const s=data.ledger,m=data.member;
 if(current==='overview')return `${heading('Welcome back, '+esc(m.name.split(' ')[0])+'.','Your membership, contributions and community—all in one place.',button('Download statement','export','','down'))}<div class="welcome-banner"><div><h2>${!data.ledgerEnabled?'Your membership records, together.':s.outstanding===0?'Thank you for standing together.':'Let’s keep your contributions up to date.'}</h2><p>${!data.ledgerEnabled?'Your opening balances are being reconciled. You can already view your historical payment records.':s.outstanding===0?'Your portal ledger has no outstanding contributions. Every contribution helps our community be there for one another.':'You have '+money(s.outstanding)+' in recorded outstanding contributions. View your statement for the details.'}</p></div><button class="btn" data-page="funds">View contributions ${icon('arrow')}</button></div>${!data.ledgerEnabled?'<div class="info-note amber" style="margin-bottom:20px">'+icon('clock')+'Opening balances are being reconciled. Portal totals are not yet a complete account balance; historical payments are available in My statement.</div>':''}<div class="metrics">${metric('Outstanding contributions',data.ledgerEnabled?money(s.outstanding):'Pending',s.outstanding?'View the breakdown below':'No outstanding portal charges','heart')}${metric('Available credit',data.ledgerEnabled?money(s.credit):'Pending','Held for future contributions','wallet','green')}${metric('Payments in this ledger',money(s.received),'Historical records listed separately','down')}</div><div class="two-col"><div><section class="card"><div class="card-head"><div><h2>Recent activity</h2><p>A clear record of every contribution.</p></div><button class="text-link" data-page="statement">View all ${icon('arrow')}</button></div>${transactions(s.events,4)}</section><section class="card"><div class="card-head"><h2>Your contributions</h2><span class="pill neutral">${s.charges.length} recorded</span></div>${fundRows(s.charges.slice(-2))}</section></div><div><section class="card"><div class="card-head"><h2>How your credit works</h2>${icon('wallet')}</div><div class="card-body"><p class="muted" style="font-size:12px">A little ahead today. Ready for tomorrow.</p><ul class="timeline"><li><span class="timeline-icon">${icon('down')}</span><div><p>You make a payment</p><small>The identified contribution is covered first.</small></div></li><li><span class="timeline-icon">${icon('wallet')}</span><div><p>The remainder stays yours</p><small>Any excess becomes available member credit.</small></div></li><li><span class="timeline-icon">${icon('check')}</span><div><p>Every use is recorded</p><small>See the fund and amount on your statement.</small></div></li></ul></div></section><section class="card"><div class="card-head"><h2>Member resources</h2></div><div class="card-body"><div class="quick-links"><button class="quick-link" data-page="documents">${icon('file')}Reports</button><button class="quick-link" data-page="messages">${icon('message')}Messages</button><button class="quick-link" data-action="help">${icon('user')}Get help</button></div></div></section><div class="info-note">${icon('shield')}<span>Your account is personal. Never share your password or verification email.</span></div></div></div>`;
 if(current==='statement'){let events=s.events.filter(e=>(filter==='all'||e.kind===filter)&&JSON.stringify([e.title,e.reference,labels[e.kind]]).toLowerCase().includes(search.toLowerCase()));return `${heading('My statement','Understand every payment, allocation and credit.',button('Download CSV','export','','down'))}<div class="filterbar"><div class="search">${icon('search')}<input id="statementSearch" placeholder="Search transactions…" aria-label="Search transactions" value="${esc(search)}"></div><select id="statementFilter" aria-label="Filter transactions">${[['all','All transactions'],['PAYMENT','Payments'],['CHARGE','Contributions'],['APPLY_CREDIT','Credit applied'],['OPENING_CREDIT','Opening credit'],['REVERSAL','Reversals'],['REFUND','Refunds']].map(([v,l])=>`<option value="${v}" ${v===filter?'selected':''}>${l}</option>`).join('')}</select></div><section class="card">${transactions(events)}</section><div class="info-note">${icon('file')}<span>Available credit: <strong>${money(s.credit)}</strong> · Outstanding: <strong>${money(s.outstanding)}</strong>. An allocation moves credit to a contribution; it is not another payment.</span></div><section class="card" style="margin-top:22px"><div class="card-head"><div><h2>Historical payment records</h2><p>Read-only records from the existing payment register. Not added again to the new ledger.</p></div></div>${data.history.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Status</th><th class="right">Amount</th></tr></thead><tbody>${data.history.map(p=>`<tr><td>${esc(p.date)}</td><td>${esc(p.type)}<small>${esc(p.fund)}</small></td><td>${esc(p.status)}</td><td class="right">${money(p.amount)}</td></tr>`).join('')}</tbody></table></div>`:empty('No historical records loaded',demo?'The preview contains fictional ledger entries only.':'No matching historical payment rows were found.')}</section>`;}
 if(current==='funds')return `${heading('Contributions & credit','Know what you owe and what is available for the next fund.',button('Payment instructions','payment-info','','wallet'))}<div class="metrics">${metric('Outstanding',data.ledgerEnabled?money(s.outstanding):'Pending','Recorded portal obligations','heart')}${metric('Available credit',data.ledgerEnabled?money(s.credit):'Pending','Unallocated member funds','wallet','green')}${metric('Contributions settled',s.charges.filter(c=>c.remaining===0).length+' / '+s.charges.length,'In the portal ledger','check')}</div><section class="card"><div class="card-head"><h2>Contribution breakdown</h2></div>${fundRows(s.charges)}</section><div class="info-note">${icon('shield')}Credit is allocated according to the organization’s approved rules. An available credit balance alone does not establish benefit eligibility.</div>`;
 if(current==='documents')return `${heading('Member documents','Official reports and records, organized in one place.')}<div class="document-grid">${data.documents.map(d=>`<article class="card doc"><div class="doc-icon">${icon('file')}</div><span class="eyebrow muted" style="margin-bottom:9px">${esc(d.category)}</span><h3>${esc(d.title)}</h3><p>${esc(d.period)} · ${date(d.date)}${demo?' · Sample':''}</p><button class="btn small" data-document="${esc(d.id)}">${icon('down')}${demo?'Open sample':'Download PDF'}</button></article>`).join('')}</div>${!data.documents.length?empty('No documents published yet','Approved reports and statements will appear here.'):''}<div class="info-note">${icon('shield')}Documents are provided for authorized members. Please handle bank statements and personal information with care.</div>`;
 if(current==='messages')return `${heading('Official messages','Announcements and your correspondence with leadership.',button('New enquiry','help','primary','plus'))}<section class="card"><div class="card-head"><h2>From leadership</h2><span class="pill neutral">${data.messages.length} messages</span></div>${data.messages.length?data.messages.map(m=>`<article class="message"><div class="message-meta"><span>${esc(m.author||'Leadership')} · ${date(m.date)}</span><span class="pill ${m.read?'neutral':''}">${m.read?'Read':'New'}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.body)}</p>${!m.read?`<button class="text-link" data-ack="${esc(m.id)}">${icon('check')} Mark as read</button>`:''}</article>`).join(''):empty('You’re up to date','New official announcements will appear here.','message')}</section><section class="card"><div class="card-head"><h2>My enquiries</h2></div>${ticketRows(data.tickets,false)}</section>`;
 if(current==='profile')return `${heading('My profile','Keep your contact information current.')}<div class="two-col"><section class="card"><div class="card-head"><h2>Membership details</h2><span class="pill neutral">${esc(m.id)}</span></div><div class="card-body"><form id="profileForm"><div class="profile-grid"><div class="field"><label>Full name</label><input value="${esc(m.name)}" disabled></div><div class="field"><label>Registered email</label><input value="${esc(m.email)}" disabled></div><div class="field"><label for="profilePhone">Phone</label><input id="profilePhone" name="phone" maxlength="40" value="${esc(m.phone)}" autocomplete="tel"></div><div class="field"><label for="profileLocation">Location</label><input id="profileLocation" name="location" maxlength="100" value="${esc(m.location)}"></div></div><p class="muted" style="font-size:11px;margin-bottom:20px">Changes are submitted to leadership for verification. Contact leadership to change your name or registered email.</p><button class="btn primary" type="submit">Submit update request</button></form></div></section><section class="card"><div class="card-head"><h2>Account security</h2>${icon('shield')}</div><div class="card-body"><p class="muted" style="font-size:12px;margin-bottom:20px">Only you know your password. Leadership can help start the recovery process, but cannot view it.</p>${button('Reset my password','self-reset','','shield')}<p class="muted" style="font-size:11px;margin-top:20px">Member since ${date(m.joined)}</p></div></section></div>`;
 if(current==='admin')return renderAdmin();return '';
}
function fundRows(charges){return charges.length?charges.slice().reverse().map(c=>`<div class="fund-row"><div class="fund-icon">${icon('heart')}</div><div class="fund-info"><h3>${esc(c.title)}</h3><p>${esc(c.key)} · ${money(c.due)} contribution</p></div><div class="fund-amount">${c.remaining?money(c.remaining):'<span class="pill">'+icon('check')+' Paid</span>'}<small>${c.remaining?'Outstanding':'Fully allocated'}</small></div></div>`).join(''):empty('No contributions recorded','Your contributions will appear after reconciliation.','heart');}
function ticketRows(tickets,admin){return tickets.length?tickets.map(t=>`<article class="message"><div class="message-meta"><span>${admin?esc(t.memberId)+' · ':''}${date(t.date)}</span><span class="pill neutral">${esc(t.status)}</span></div><h3>${esc(t.subject)}</h3><p>${esc(t.body)}</p>${t.reply?'<div class="info-note" style="margin-top:15px">'+esc(t.reply)+'</div>':''}${admin?'<button class="text-link" data-reply="'+esc(t.id)+'">Reply '+icon('arrow')+'</button>':''}</article>`).join(''):empty('No enquiries yet','Questions and responses will be kept here.','message');}
function renderAdmin(){const a=data.admin;if(!a)return empty('Admin access required','This account does not have administrator permissions.','shield');let body='';
 if(adminTab==='members')body=`<section class="card"><div class="card-head"><div><h2>Member accounts</h2><p>Account access is separate from membership and benefit eligibility.</p></div><span class="pill neutral">${a.members.length} members</span></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Account</th><th class="right">Credit</th><th class="right">Outstanding</th><th>Manage</th></tr></thead><tbody>${a.members.map(m=>`<tr><td><div class="member-name"><span class="avatar">${esc(initials(m.name))}</span><div>${esc(m.name)}<small>${esc(m.id)} · ${esc(m.email)}</small></div></div></td><td><span class="pill ${m.status==='SUSPENDED'?'amber':'neutral'}">${esc(m.status||'ACTIVE')}</span></td><td class="right">${money(m.credit)}</td><td class="right">${money(m.outstanding)}</td><td><button class="text-link" data-manage="${esc(m.id)}">Manage ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div></section>`;
 if(adminTab==='ledger')body=`<div class="info-note amber" style="margin-bottom:20px">${icon('shield')}<span>${demo?'Preview transactions change fictional balances only.':'Before posting, reconcile opening balances and select the correct member and payment reference. Original payment and TRACK sheets are not modified.'}</span></div><section class="card"><div class="card-head"><h2>Member ledger</h2>${button('Record transaction','ledger-form','primary','plus')}</div>${transactions(a.events)}</section>`;
 if(adminTab==='documents')body=`<section class="card"><div class="card-head"><h2>Document library</h2>${button('Publish document','document-form','primary','plus')}</div><div class="table-wrap"><table><thead><tr><th>Document</th><th>Audience</th><th>Published</th></tr></thead><tbody>${a.documents.map(d=>`<tr><td>${esc(d.title)}<small>${esc(d.category)} · ${esc(d.period)}</small></td><td>${esc(d.audience)}</td><td>${date(d.date)}</td></tr>`).join('')}</tbody></table></div></section>`;
 if(adminTab==='messages')body=`<section class="card"><div class="card-head"><h2>Announcements</h2>${button('New announcement','message-form','primary','plus')}</div>${a.messages.map(m=>`<article class="message"><div class="message-meta">${esc(m.audience)} · ${date(m.date)}</div><h3>${esc(m.title)}</h3><p>${esc(m.body)}</p></article>`).join('')}</section><section class="card"><div class="card-head"><h2>Member enquiries</h2></div>${ticketRows(a.tickets,true)}</section>`;
 if(adminTab==='audit')body=`<section class="card"><div class="card-head"><h2>Activity log</h2><span class="pill neutral">Recorded actions</span></div>${a.audit.length?`<div class="table-wrap"><table><thead><tr><th>When</th><th>Who</th><th>Action</th></tr></thead><tbody>${a.audit.map(e=>`<tr><td>${date(e.at)}</td><td>${esc(e.actor)}</td><td>${esc(e.action)}</td></tr>`).join('')}</tbody></table></div>`:empty('No administrative actions yet','Account changes, document access and transactions are recorded here.','clock')}</section>`;
 return `${heading('Admin workspace','Manage accounts, reconcile credit and keep members informed.')}<div class="admin-tabs">${[['members','Members'],['ledger','Payments & credit'],['documents','Documents'],['messages','Messages'],['audit','Activity log']].map(([id,l])=>`<button class="${adminTab===id?'active':''}" data-admin-tab="${id}">${l}</button>`).join('')}</div>${body}`;
}
function field(label,name,type='text',value='',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function selectField(label,name,opts){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${opts.map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('')}</select></div>`;}
function formFooter(label){return `<div class="error-text" role="alert"></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">${label}</button></div>`;}
function openLedger(){modal('Record a transaction',`<form id="ledgerForm">${selectField('Member','memberId',data.admin.members.map(m=>[m.id,m.id+' · '+m.name]))}${selectField('Transaction','kind',[['PAYMENT','Confirmed payment'],['CHARGE','Contribution obligation'],['OPENING_CREDIT','Reconciled opening credit'],['APPLY_CREDIT','Apply available credit'],['REFUND','Record completed credit refund'],['REVERSAL','Reverse a payment']])}<div id="ledgerFields"></div><div class="field"><label for="f-note">Reason / reconciliation note</label><textarea id="f-note" name="note" required maxlength="1000" placeholder="Explain the source and purpose of this entry."></textarea></div>${formFooter(demo?'Record sample transaction':'Post transaction')}</form>`);updateLedgerFields();}
function updateLedgerFields(){const form=$('#ledgerForm');if(!form)return;const kind=form.elements.kind.value,mid=form.elements.memberId.value;const events=demo?model.events:data.admin.events,s=MWLedger.state(events,mid);let html='';if(kind!=='APPLY_CREDIT'&&kind!=='REVERSAL')html+=field('Amount ($)','amount','number','','min="0.01" max="1000000" step="0.01" required');if(kind==='PAYMENT')html+=field('Unique bank / payment reference','reference','text','','required maxlength="100"')+selectField('Apply payment to','scope',[['oldest','Oldest outstanding contributions'],['advance','Advance credit only'],...s.charges.filter(c=>c.remaining>0).map(c=>[c.id,c.title+' · '+money(c.remaining)])]);if(kind==='CHARGE')html+=field('Unique obligation key','chargeKey','text','','placeholder="FUND-009" required maxlength="80"')+field('Description','title','text','','placeholder="Fund 009 contribution" required maxlength="150"');if(kind==='REVERSAL')html+=selectField('Original payment','targetId',events.filter(e=>e.memberId===mid&&e.kind==='PAYMENT').map(e=>[e.id,e.reference+' · '+money(e.amount)]));html+=`<div class="info-note">Available credit: ${money(s.credit)} · Outstanding: ${money(s.outstanding)}</div>`;$('#ledgerFields').innerHTML=html;}
function download(name,text,mime='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:mime}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportStatement(){const safe=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Date','Type','Description','Amount USD','Reference','Allocation details'],...data.ledger.events.map(e=>[e.at,labels[e.kind],e.title,(e.amount/100).toFixed(2),e.reference||'',(e.allocations||[]).map(a=>a.chargeId+': '+money(a.amount)).join('; ')])];download('Mgwirizano_'+data.member.id+'_statement.csv',rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv');toast('Statement downloaded.');}
async function openDocument(id){if(demo){const d=model.documents.find(d=>d.id===id);modal('Sample document',`<div class="info-note amber">Preview only · This is not an official financial report or bank statement.</div><h3 style="margin:20px 0 10px">${esc(d.title)}</h3><p class="muted">The live portal will retrieve the approved PDF after checking your account and document permissions.</p><div class="modal-foot">${button('Close','close-modal','primary')}</div>`);return;}const d=await rpc('document',{id});const binary=atob(d.base64),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));download(d.name,bytes,'application/pdf');}
function renderAuth(mode='signin',error=''){document.body.classList.toggle('live',!demo);const signup=mode==='signup',reset=mode==='reset';$('#app').innerHTML=`<div class="auth-page"><div class="auth-brand">${brand()}<h1>Standing together.<br>Every step of the way.</h1><p>Your contributions, your records, your community. Welcome to your Mgwirizano member account.</p></div><div class="auth-form"><div><div class="eyebrow muted" style="margin-bottom:15px">${demo?'PREVIEW · NO LIVE LOGIN':'YOUR MEMBER ACCOUNT'}</div><h1>${signup?'Activate your account':reset?'Reset your password':'Welcome back.'}</h1><p class="subtitle">${signup?'Use the email address already registered with Mgwirizano.':'Access your membership securely.'}</p><form id="authForm" data-mode="${mode}">${field('Email address','email','email','','required autocomplete="email"')}${!reset?field('Password','password','password','','required minlength="12" autocomplete="'+(signup?'new-password':'current-password')+'"'):''}<div class="error-text" role="alert">${esc(error)}</div><button type="submit" class="btn primary">${signup?'Create account':reset?'Send reset email':'Sign in'} ${icon('arrow')}</button></form><div class="auth-links"><button class="text-link" data-auth="${signup||reset?'signin':'signup'}">${signup||reset?'Back to sign in':'First visit? Activate account'}</button>${!reset?'<button class="text-link" data-auth="reset">Forgot password?</button>':''}</div>${!demo&&auth?'<button class="text-link" data-action="verify-email" style="margin-top:15px">Resend verification email</button>':''}${demo?'<button class="btn" data-action="enter-demo" style="width:100%;margin-top:25px">Explore sample member account '+icon('arrow')+'</button>':''}<p class="auth-foot">Need help? <a href="mailto:admin@mgwirizano.net">Contact leadership</a><br>Passwords are never shared with administrators.</p></div></div></div>`;}
async function handleAction(action,el){
 if(action==='menu'){document.body.classList.toggle('menu-open');return;}
 if(action==='close-modal'){$('#modal').close();return;}
 if(action==='export'){exportStatement();return;}
 if(action==='reset-demo'){model=seed();save();await refresh();toast('Sample records reset.');return;}
 if(action==='logout'){auth=null;data=null;adminView=false;renderAuth();return;}
 if(action==='login-preview'){renderAuth();return;}
 if(action==='enter-demo'){current='overview';await refresh();return;}
 if(action==='help'){modal('Contact leadership',`<form id="helpForm">${field('Subject','subject','text','','required maxlength="120"')}<div class="field"><label for="f-body">How can we help?</label><textarea id="f-body" name="body" required maxlength="3000" placeholder="Include the payment date and reference if relevant. Do not include passwords or full bank account details."></textarea></div>${formFooter(demo?'Save sample enquiry':'Send enquiry')}</form>`);return;}
 if(action==='payment-info'){modal('Making a contribution',`<p>Payments continue through the organization’s existing Zelle process.</p><div class="info-note" style="margin-top:17px">Use your Member ID and the deceased’s last name in the memo, following the official fund notice. For advance payments, follow the instructions approved by leadership.</div><p class="muted" style="margin-top:17px;font-size:12px">This portal records confirmed payments; it does not collect card or bank details.</p><div class="modal-foot">${button('Done','close-modal','primary')}</div>`);return;}
 if(action==='verify-email'){await firebaseRequest('sendOobCode',{requestType:'VERIFY_EMAIL',idToken:await token()});toast('Verification email requested. Check your inbox.');return;}
 if(action==='self-reset'){if(demo){toast('Preview only. No reset email sent.');return;}await firebaseRequest('sendOobCode',{requestType:'PASSWORD_RESET',email:data.member.email});toast('Check your registered email for password-reset instructions.');return;}
 if(action==='ledger-form'){openLedger();return;}
 if(action==='document-form'||action==='message-form'){const doc=action==='document-form';modal(doc?'Publish a document':'New announcement',`<form id="publishForm" data-type="${doc?'document':'message'}">${field('Title','title','text','','required maxlength="150"')}${selectField('Audience','audience',[['members','All active portal members'],['board','Board / administrators']])}${doc?field('Category','category','text','Quarterly report','required maxlength="60"')+field('Reporting period','period','text','','placeholder="Q3 2026" required maxlength="60"')+field('Private Drive PDF file ID','fileId','text','','placeholder="File ID from Google Drive" '+(demo?'':'required')+' maxlength="160"')+'<p class="muted" style="font-size:11px">PDFs only, up to 5 MB. Keep the file private in the approved document folder.</p>':'<div class="field"><label for="f-body">Message</label><textarea id="f-body" name="body" required maxlength="5000"></textarea></div>'}${formFooter(demo?'Publish sample':'Publish')}</form>`);return;}
}
document.addEventListener('click',async ev=>{const el=ev.target.closest('button,[data-action]');if(!el)return;try{
 if(el.dataset.page){current=el.dataset.page;search='';filter='all';document.body.classList.remove('menu-open');if(current==='admin'&&demo){adminView=true;await refresh();}else render();window.scrollTo(0,0);}
 else if(el.dataset.adminTab){adminTab=el.dataset.adminTab;render();}
 else if(el.dataset.action)await handleAction(el.dataset.action,el);
 else if(el.dataset.auth)renderAuth(el.dataset.auth);
 else if(el.dataset.document){el.disabled=true;await openDocument(el.dataset.document);}
 else if(el.dataset.ack){await rpc('acknowledge',{id:el.dataset.ack});await refresh();}
 else if(el.dataset.manage){const m=data.admin.members.find(m=>m.id===el.dataset.manage);modal('Manage account',`<h3>${esc(m.name)}</h3><p class="muted" style="margin:4px 0 20px">${esc(m.id)} · ${esc(m.email)}</p><div class="info-note">Access changes do not delete financial records or change membership benefits.</div><div class="modal-foot"><button class="btn" data-reset-member="${esc(m.id)}">Send reset email</button><button class="btn primary" data-status-member="${esc(m.id)}" data-status="${m.status==='SUSPENDED'?'ACTIVE':'SUSPENDED'}">${m.status==='SUSPENDED'?'Restore access':'Suspend access'}</button></div>`);}
 else if(el.dataset.resetMember){el.disabled=true;const r=await rpc('resetPassword',{memberId:el.dataset.resetMember});toast(r.message||'Password-reset request sent.');}
 else if(el.dataset.statusMember){el.disabled=true;await rpc('accountStatus',{memberId:el.dataset.statusMember,status:el.dataset.status});$('#modal').close();await refresh();toast('Account access updated.');}
 else if(el.dataset.reply){modal('Reply to enquiry',`<form id="replyForm" data-id="${esc(el.dataset.reply)}"><div class="field"><label for="f-reply">Reply</label><textarea id="f-reply" name="reply" required maxlength="3000"></textarea></div>${formFooter('Save reply')}</form>`);}
 }catch(e){toast(e.message);}finally{if(el.isConnected)el.disabled=false;}});
document.addEventListener('change',ev=>{if(ev.target.id==='statementFilter'){filter=ev.target.value;render();}if(ev.target.closest('#ledgerForm')&&['kind','memberId'].includes(ev.target.name))updateLedgerFields();});
document.addEventListener('input',ev=>{if(ev.target.id==='statementSearch'){const pos=ev.target.selectionStart;search=ev.target.value;render();$('#statementSearch').focus();$('#statementSearch').setSelectionRange(pos,pos);}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target,p=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{
 if(form.id==='authForm'){
   if(demo){form.querySelector('.error-text').textContent='This is a preview. Use “Explore sample member account” below; no credentials are sent.';return;}
   if(!boot.apiKey||!window.google?.script?.run)throw new Error('The secure portal is not configured yet. Contact leadership.');
   const mode=form.dataset.mode;
   if(mode==='reset'){try{await firebaseRequest('sendOobCode',{requestType:'PASSWORD_RESET',email:p.email});}catch(e){}toast('If an account exists, reset instructions will be sent.');return;}
   const r=await firebaseRequest(mode==='signup'?'signUp':'signInWithPassword',{email:p.email,password:p.password,returnSecureToken:true});
   if(mode==='signup'){await firebaseRequest('sendOobCode',{requestType:'VERIFY_EMAIL',idToken:r.idToken});renderAuth('signin');toast('Check your email to verify your account, then sign in.');return;}
   auth={idToken:r.idToken,refreshToken:r.refreshToken,expires:Date.now()+(Number(r.expiresIn)-60)*1000};current='overview';await refresh();return;
 }
 if(form.id==='ledgerForm'){p.requestId=form.dataset.requestId||(form.dataset.requestId=uid());await rpc('ledger',p);}
 if(form.id==='helpForm')await rpc('ticket',p);
 if(form.id==='profileForm')await rpc('profileRequest',p);
 if(form.id==='replyForm')await rpc('reply',{...p,id:form.dataset.id});
 if(form.id==='publishForm')await rpc('publish',{...p,type:form.dataset.type});
 if($('#modal').open)$('#modal').close();await refresh();toast(demo?'Saved to this preview. No live records changed.':'Saved successfully.');
 }catch(e){const target=form.querySelector('.error-text');if(target)target.textContent=form.id==='authForm'?'Unable to complete sign-in. Check your credentials and email verification, or use password recovery.':e.message;else toast(e.message);}finally{if(submit?.isConnected)submit.disabled=false;}});
if(demo)refresh();else renderAuth();
})();
